import type { Channel, ConsumeMessage } from 'amqplib';

export interface ConsumerOptions {
  channel: Channel;
  queue: string;
  dlqQueue?: string;
  onMessage: (content: unknown, rawMessage: ConsumeMessage) => Promise<void>;
}

export async function setupConsumer({
  channel,
  queue,
  dlqQueue = `${queue}.dlq`,
  onMessage,
}: ConsumerOptions): Promise<void> {
  const dlxExchange = `${queue}.dlx`;
  await channel.assertExchange(dlxExchange, 'direct', { durable: true });
  await channel.assertQueue(dlqQueue, { durable: true });
  await channel.bindQueue(dlqQueue, dlxExchange, 'failed');

  await channel.assertQueue(queue, {
    durable: true,
    arguments: {
      'x-dead-letter-exchange': dlxExchange,
      'x-dead-letter-routing-key': 'failed',
    },
  });

  await channel.prefetch(1);

  console.log(` [*] Esperando mensajes en la cola: ${queue}`);

  channel.consume(
    queue,
    async (msg) => {
      if (!msg) return;

      try {
        const content = JSON.parse(msg.content.toString());
        await onMessage(content, msg);
        
        channel.ack(msg);
      } catch (error) {
        console.error(` [!] Error procesando mensaje en cola ${queue}:`, error);

        channel.nack(msg, false, false);
      }
    },
    { noAck: false }
  );
}